/**
 * UNO's browser-side sharing authority.
 *
 * Social crawlers read the static OG/Twitter tags generated by
 * scripts/apply_global_share_previews.py; they do not run this module.
 * Individual /share/UNO-007/ links retain their own card preview.
 */
(()=>{
  'use strict';
  if (window.ChansonSocialShare) return;

  const SITE_ORIGIN = 'https://www.chanson-a-repondre-uno.scot';
  const PREVIEW_URL = SITE_ORIGIN + '/social/chanson-a-repondre-uno-share.png';
  const nativeShare = typeof navigator.share === 'function'
    ? navigator.share.bind(navigator) : null;
  const nativeCanShare = typeof navigator.canShare === 'function'
    ? navigator.canShare.bind(navigator) : null;

  function minimalUrl(input) {
    let url;
    try { url = new URL(input || location.href, location.href); }
    catch (_) { return SITE_ORIGIN + '/'; }

    // Never rewrite external links, including their query parameters.
    if (url.origin !== SITE_ORIGIN && url.origin !== location.origin) return url.href;
    url.protocol = 'https:';
    url.host = 'www.chanson-a-repondre-uno.scot';
    url.username = '';
    url.password = '';
    url.search = '';

    let path = url.pathname.replace(/\/index\.html$/i, '/').replace(/\/{2,}/g, '/');
    if (!path.startsWith('/')) path = '/' + path;
    if (/^\/enochian-test\//i.test(path) || /^\/enochian-terminal-live\/?$/i.test(path)) {
      path = '/enochian-terminal/';
    }
    if (!path.endsWith('/') && !/\.[a-z0-9]{2,5}$/i.test(path)) path += '/';
    url.pathname = path;

    // Hash routes are useful for navigation, but social scrapers ignore them.
    // A card must be shared through its server-rendered /share/<slug>/ page.
    if (path === '/') {
      const route = url.hash.match(/^#\/[A-Za-z0-9_\-/]+/);
      url.hash = route ? route[0] : '';
    } else {
      url.hash = '';
    }
    return url.href;
  }

  function isCardShareUrl(input) {
    try { return /^\/share\/(?:UNO|BRIO|HP)-\d+\/$/i.test(new URL(input).pathname); }
    catch (_) { return false; }
  }

  async function share(data = {}) {
    if (!nativeShare) throw new TypeError('Web Share API unavailable');
    const payload = { ...data, url: minimalUrl(data.url || location.href) };
    // Do not attach a generic image: attaching a File changes the share
    // target on some platforms and hides the per-card OG preview.
    // Explicit card-image Files supplied by callers are still supported.
    if (payload.files && (!nativeCanShare || !nativeCanShare(payload))) {
      delete payload.files;
    }
    return nativeShare(payload);
  }

  async function copyLink(input) {
    const url = minimalUrl(input || location.href);
    if (!navigator.clipboard || typeof navigator.clipboard.writeText !== 'function') {
      throw new TypeError('Clipboard API unavailable');
    }
    await navigator.clipboard.writeText(url);
    return url;
  }

  window.ChansonSocialShare = Object.freeze({
    version: 'v2',
    previewUrl: PREVIEW_URL,
    minimalUrl,
    isCardShareUrl,
    share,
    copyLink,
  });

  // Preserve existing callers that use navigator.share directly.
  // Only normalise URLs; never silently attach an unrelated preview file.
  if (nativeShare) {
    try {
      Object.defineProperty(navigator, 'share', {
        configurable: true, enumerable: true, value: share,
      });
    } catch (_) {}
  }
})();
